# Transcription of the four King / Devil monsters (owner scans 2026-11-19). Writes docs/transcriptions/<id>_raw.json.
# Icons: [V]=Vigor, [H]=Heat, [P]=Passion, [Peril]=Peril Check, [Armor]=Armor token, [Gear]=Gear card, [Bane]=Bane token, [die]=Evasion die, [React]=REACT! window.
# Gates are written "{H4+: +1 [die]}" (stat, threshold, effect). Engine support for these monsters is NOT implemented yet.
import json, os
OUT = os.path.join(os.path.dirname(__file__), '..', '..', 'docs', 'transcriptions')
def A(name, lv, typ, dice, diff, tg, tag, eff, after=None, afterTag='AFTER ATTACK', pre=None, zone=None, unclear=None):
    return dict(name=name, level=lv, type=typ, evasionDice=dice, evasionDifficulty=diff, pre=pre, targeting=tg, tag=tag, effects=eff, afterTag=afterTag if after else None, after=after, zone=zone, unclear=unclear or [])
def B(name, lv, at, top=None, w=None, f=None, i=None, c=None, note=None, unclear=None):
    return dict(name=name, level=lv, at=at, top=top, note=note, wound=w, fail=f, instinct=i, critical=c, unclear=unclear or [])
def L(toHit, esc=0, at=0, vig=0, ev=0, heat=0, traits=()):
    return dict(toHit=toHit, wounds=10, exhibitionWounds=3, activations=['AI', 'S'], traitsAdd=list(traits), bonuses=dict(escalations=esc, at=at, vigorLoss=vig, evasionDice=ev, heat=heat))
T = lambda n, lv, t: dict(name=n, level=lv, text=t)
CF = ['Closest Knight in front', 'Closest Knight in sight']; FF = ['Furthest Knight in front', 'Furthest Knight in sight']; VP = ['Knight on the VP']
MA = 'MOVE & ATTACK'; PB = 'You may Bargain before the Power Roll.'

